package com.rustypayments.legacy;

import com.rustypayments.PaymentCalendar;
import java.time.*;
import java.time.format.*;
import java.time.temporal.ChronoUnit;
import java.util.Set;

public class LegacyPaymentCalendar implements PaymentCalendar {
    private static final ZoneId WARSAW = ZoneId.of("Europe/Warsaw");
    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    private static final Set<MonthDay> HOLIDAYS = Set.of(
            MonthDay.of(1, 1),
            MonthDay.of(1, 6),
            MonthDay.of(5, 1),
            MonthDay.of(5, 3),
            MonthDay.of(8, 15),
            MonthDay.of(11, 1),
            MonthDay.of(11, 11),
            MonthDay.of(12, 25),
            MonthDay.of(12, 26)
    );

    @Override
    public boolean isBusinessDay(String date) {
        LocalDate d = parseDate(date);
        return isBusinessDay(d);
    }

    private boolean isBusinessDay(LocalDate d) {
        DayOfWeek dow = d.getDayOfWeek();
        if (dow == DayOfWeek.SATURDAY || dow == DayOfWeek.SUNDAY) {
            return false;
        }
        return !HOLIDAYS.contains(MonthDay.from(d));
    }

    @Override
    public String processingDate(String submittedAt) {
        ZonedDateTime warsawZdt = parseInstant(submittedAt).withZoneSameInstant(WARSAW);
        LocalDate localDate = warsawZdt.toLocalDate();
        LocalTime localTime = warsawZdt.toLocalTime();
        LocalTime cutOff = LocalTime.of(16, 0, 0);

        if (isBusinessDay(localDate) && !localTime.isAfter(cutOff)) {
            return localDate.format(DATE_FORMATTER);
        } else {
            return nextBusinessDay(localDate).format(DATE_FORMATTER);
        }
    }

    @Override
    public String settlementDate(String submittedAt) {
        LocalDate procDate = LocalDate.parse(processingDate(submittedAt), DATE_FORMATTER);
        return nextBusinessDay(procDate).format(DATE_FORMATTER);
    }

    @Override
    public int daysLate(String dueDate, String paidAt) {
        LocalDate due = parseDate(dueDate);
        LocalDate paid = parseInstant(paidAt).withZoneSameInstant(WARSAW).toLocalDate();
        long late = ChronoUnit.DAYS.between(due, paid);
        return late < 0 ? 0 : (int) late;
    }

    @Override
    public String addMonths(String date, int months) {
        LocalDate start = parseDate(date);
        boolean wasEndOfMonth = (start.getDayOfMonth() == start.lengthOfMonth());
        LocalDate result = start.plusMonths(months);
        if (wasEndOfMonth) {
            result = result.withDayOfMonth(result.lengthOfMonth());
        }
        return result.format(DATE_FORMATTER);
    }

    private LocalDate nextBusinessDay(LocalDate from) {
        LocalDate d = from.plusDays(1);
        while (!isBusinessDay(d)) {
            d = d.plusDays(1);
        }
        return d;
    }

    private LocalDate parseDate(String date) {
        if (date == null || !date.matches("\\d{4}-\\d{2}-\\d{2}")) {
            throw new IllegalArgumentException("Invalid date format");
        }
        try {
            return LocalDate.parse(date, DATE_FORMATTER);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid date", e);
        }
    }

    private ZonedDateTime parseInstant(String instant) {
        if (instant == null) {
            throw new IllegalArgumentException("Instant is null");
        }
        try {
            return ZonedDateTime.parse(instant);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid instant", e);
        }
    }
}

